mapper.select:
SELECT id, user_id, name, description, archived_at, deleted_at, created_at, updated_at
FROM assistant_project
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
LIMIT 1

mapper.update:
UPDATE assistant_project
SET deleted_at = #{deletedAt},
    updated_at = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
